1	import type { MailAddress } from "@/lib/mail/types";
2	
3	/* -------------------------------------------------------------------------- */
4	/* Presentation helpers shared across the mail UI                              */
5	/* -------------------------------------------------------------------------- */
6	
7	/** Display name for an address: prefer the friendly name, fall back to the
8	 *  local part of the email (before the @). */
9	export function displayName(a?: MailAddress | null): string {
10	  if (!a) return "Unknown";
11	  if (a.name && a.name.trim()) return a.name.trim();
12	  const at = a.address.indexOf("@");
13	  return at > 0 ? a.address.slice(0, at) : a.address || "Unknown";
14	}
15	
16	/** Up-to-two-letter initials from a name or address. */
17	export function initials(a?: MailAddress | null): string {
18	  const name = displayName(a);
19	  const parts = name.replace(/[^\p{L}\p{N} ]/gu, " ").trim().split(/\s+/).filter(Boolean);
20	  if (parts.length === 0) return "?";
21	  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
22	  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
23	}
24	
25	/** Deterministic on-brand gradient for an avatar, derived from the address so a
26	 *  given sender always gets the same colour. Hues are pulled toward the violet /
27	 *  blue / cyan Nxeon range with a couple of warm accents for variety. */
28	const AVATAR_GRADIENTS = [
29	  "from-brand-500 to-accent-blue",
30	  "from-accent-blue to-brand-400",
31	  "from-brand-400 to-fuchsia-500",
32	  "from-accent-cyan to-accent-blue",
33	  "from-violet-500 to-brand-600",
34	  "from-sky-500 to-brand-500",
35	  "from-brand-600 to-violet-400",
36	  "from-emerald-500 to-accent-cyan",
37	  "from-rose-500 to-brand-500",
38	  "from-amber-500 to-rose-500",
39	];
40	
41	export function avatarGradient(seed: string): string {
42	  let h = 0;
43	  for (let i = 0; i < seed.length; i++) h = (h * 31 + seed.charCodeAt(i)) >>> 0;
44	  return AVATAR_GRADIENTS[h % AVATAR_GRADIENTS.length];
45	}
46	
47	/** Compact list timestamp: time for today, "Mon" for this week, else a short date. */
48	export function shortDate(iso: string): string {
49	  const d = new Date(iso);
50	  if (Number.isNaN(d.getTime())) return "";
51	  const now = new Date();
52	  const sameDay =
53	    d.getFullYear() === now.getFullYear() &&
54	    d.getMonth() === now.getMonth() &&
55	    d.getDate() === now.getDate();
56	  if (sameDay) return d.toLocaleTimeString([], { hour: "numeric", minute: "2-digit" });
57	  const diffDays = (now.getTime() - d.getTime()) / 86_400_000;
58	  if (diffDays < 7 && diffDays > 0) return d.toLocaleDateString([], { weekday: "short" });
59	  const sameYear = d.getFullYear() === now.getFullYear();
60	  return d.toLocaleDateString([], sameYear ? { month: "short", day: "numeric" } : { month: "short", day: "numeric", year: "2-digit" });
61	}
62	
63	/** Verbose header timestamp for the reading pane. */
64	export function fullDate(iso: string): string {
65	  const d = new Date(iso);
66	  if (Number.isNaN(d.getTime())) return "";
67	  return d.toLocaleString([], {
68	    weekday: "short",
69	    month: "short",
70	    day: "numeric",
71	    year: "numeric",
72	    hour: "numeric",
73	    minute: "2-digit",
74	  });
75	}
76	
77	export function fmtBytesShort(b: number): string {
78	  if (!b || b <= 0) return "0 B";
79	  const units = ["B", "KB", "MB", "GB", "TB"];
80	  const i = Math.min(Math.floor(Math.log(b) / Math.log(1024)), units.length - 1);
81	  return `${(b / 1024 ** i).toFixed(i === 0 ? 0 : 1)} ${units[i]}`;
82	}
83	
84	/** Format a list of addresses as "Alice, Bob +2". */
85	export function joinAddresses(list: MailAddress[], max = 3): string {
86	  if (!list || list.length === 0) return "—";
87	  const names = list.slice(0, max).map(displayName);
88	  const extra = list.length - max;
89	  return names.join(", ") + (extra > 0 ? ` +${extra}` : "");
90	}
