93	/* Client-side category heuristics (Primary / Promotions / Social tabs)        */
94	/* -------------------------------------------------------------------------- */
95	
96	export type MailTab = "primary" | "promotions" | "social";
97	
98	const PROMO_RE = /(newsletter|deal|sale|% off|unsubscribe|promo|offer|coupon|discount|marketing|no-?reply|noreply|billing|receipt|invoice|order)/i;
99	const SOCIAL_DOMAINS = /(facebook|instagram|twitter|x\.com|linkedin|github|reddit|discord|slack|notifications?|youtube|tiktok|pinterest|medium)/i;
100	
101	export function categoryOf(from: MailAddress, subject: string): MailTab {
102	  const hay = `${from.address} ${from.name ?? ""} ${subject}`;
103	  if (SOCIAL_DOMAINS.test(from.address) || SOCIAL_DOMAINS.test(from.name ?? "")) return "social";
104	  if (PROMO_RE.test(hay)) return "promotions";
105	  return "primary";
106	}
