"use client";

import { useEffect, useState } from "react";
import type { MessageFull, MessageSummary } from "@/lib/mail/types";
import { listMessages } from "@/lib/actions-mail";
import { Icon, initials, displayName, avatarGradient, categoryOf, shortDate } from "./util";

export function ContactPanel({
  message,
  folderLabel,
  currentFolder,
  mailboxAddress,
  onCompose,
  onOpenMessage,
}: {
  message: MessageFull | null;
  folderLabel: string;
  currentFolder: string;
  mailboxAddress?: string;
  onCompose: (to: string) => void;
  onOpenMessage: (m: MessageSummary) => void;
}) {
  const [related, setRelated] = useState<MessageSummary[]>([]);

  // Load recent messages from the same sender. Fail soft — the section simply
  // stays hidden when the search errors or returns nothing.
  const senderAddress = message?.from.address;
  const openUid = message?.uid;
  useEffect(() => {
    if (!senderAddress || !currentFolder) {
      setRelated([]);
      return;
    }
    let cancelled = false;
    (async () => {
      try {
        const res = await listMessages(currentFolder, 1, senderAddress, mailboxAddress);
        if (cancelled) return;
        const items = res.messages
          .filter(
            (m) => m.uid !== openUid && m.from.address.toLowerCase() === senderAddress.toLowerCase(),
          )
          .slice(0, 5);
        setRelated(items);
      } catch {
        if (!cancelled) setRelated([]);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [senderAddress, openUid, currentFolder, mailboxAddress]);

