/** Bucket a (newest-first) list of messages into day groups, preserving order. */
function groupByDay(messages: MessageSummary[]): { label: string; items: MessageSummary[] }[] {
  const groups: { label: string; items: MessageSummary[] }[] = [];
  let current: { label: string; items: MessageSummary[] } | null = null;
  for (const m of messages) {
    const label = dayLabel(m.date);
    if (!current || current.label !== label) {
      current = { label, items: [] };
      groups.push(current);
    }
    current.items.push(m);
  }
  return groups;
}

