/* ---- Keyboard shortcuts ---------------------------------------------- */
// Messages currently visible in the list (after the category-tab filter),
// used to move the j/k selection cursor.
const visibleMessages = list.messages.filter((m) => categoryOf(m.from, m.subject) === tab);

const scrollRowIntoView = (uid: number) => {
  requestAnimationFrame(() => {
    document.querySelector(`[data-mail-uid="${uid}"]`)?.scrollIntoView({ block: "nearest" });
  });
};

const moveCursor = (dir: 1 | -1) => {
  if (visibleMessages.length === 0) return;
  const curId = cursorUid ?? selectedUid;
  let idx = visibleMessages.findIndex((m) => m.uid === curId);
  if (idx === -1) idx = dir === 1 ? -1 : 0;
  const next = Math.max(0, Math.min(visibleMessages.length - 1, idx + dir));
  const target = visibleMessages[next];
  if (target) {
    setCursorUid(target.uid);
    scrollRowIntoView(target.uid);
  }
};

const openCursor = () => {
  const id = cursorUid ?? selectedUid;
  const m = visibleMessages.find((x) => x.uid === id);
  if (m) openMessage(m);
};

// A single always-current handler behind a stable ref so the window listener
// is bound once yet never reads stale state.
const keyHandlerRef = useRef<(e: KeyboardEvent) => void>(() => {});
keyHandlerRef.current = (e: KeyboardEvent) => {
  if (showHelp) {
    if (e.key === "Escape" || e.key === "?") {
      e.preventDefault();
      setShowHelp(false);
    }
    return;
  }
  // The Composer owns its own keys while it's open.
  if (draft) return;

  const el = document.activeElement as HTMLElement | null;
  const typing =
    !!el && (el.tagName === "INPUT" || el.tagName === "TEXTAREA" || el.tagName === "SELECT" || el.isContentEditable);
  if (typing) {
    if (e.key === "Escape") el?.blur();
    return;
  }
  if (e.metaKey || e.ctrlKey || e.altKey) return;

  switch (e.key) {
    case "j": e.preventDefault(); moveCursor(1); break;
    case "k": e.preventDefault(); moveCursor(-1); break;
    case "Enter":
    case "o": e.preventDefault(); openCursor(); break;
    case "r": if (message) { e.preventDefault(); openReply(false); } break;
    case "a": if (message) { e.preventDefault(); openReply(true); } break;
    case "f": if (message) { e.preventDefault(); openForward(); } break;
    case "e": if (message) { e.preventDefault(); doArchive(); } break;
    case "#": if (message) { e.preventDefault(); doDelete(); } break;
    case "s": if (message) { e.preventDefault(); toggleStar(message); } break;
    case "c": e.preventDefault(); openCompose(); break;
    case "/": e.preventDefault(); document.getElementById("mail-search-input")?.focus(); break;
    case "?": e.preventDefault(); setShowHelp(true); break;
    case "Escape":
      e.preventDefault();
      setSelectedUid(null);
      setCursorUid(null);
      setMessage(null);
      setMobilePane("list");
      break;
    default: break;
  }
};

useEffect(() => {
  const onKey = (e: KeyboardEvent) => keyHandlerRef.current(e);
  window.addEventListener("keydown", onKey);
  return () => window.removeEventListener("keydown", onKey);
}, []);

